:root {
  --card-bg: #fdf8ee;
  --card-border: #c4a96b;
  --header-bg: #4a6741;
  --header-text: #f5edd8;
  --label-text: #6b4f1e;
  --name-color: #2d3a1e;
  --common-color: #7a6240;
  --tag-annual-bg: #d4e8cf;
  --tag-annual-text: #2e5a27;
  --tag-edible-bg: #fde8c0;
  --tag-edible-text: #7a4a0a;
  --tag-pollinator-bg: #e8d4f0;
  --tag-pollinator-text: #5a2d7a;
  --stat-bg: #f0e8d4;
  --stat-label-color: #8a6a3a;
  --stat-value-color: #2d3a1e;
  --footer-bg: #4a6741;
  --footer-text: #d4e8cf;
  --divider-color: #c4a96b;
}

.seed-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 10px;
  width: 460px;
  overflow: hidden;
  font-size: 14px;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.card-label {
  color: var(--header-text);
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.card-id {
  color: var(--header-text);
  font-size: 12px;
  opacity: 0.85;
}

.card-body {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  border-bottom: 1px dashed var(--divider-color);
}

.seed-icon {
  font-size: 48px;
  margin: 0;
  line-height: 1;
  flex-shrink: 0;
  background-color: var(--stat-bg);
  border-radius: 50%;
  width: 72px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--card-border);
}

.seed-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.seed-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--name-color);
  margin: 0;
  font-style: italic;
}

.seed-common {
  font-size: 13px;
  color: var(--common-color);
  margin: 0;
}

.seed-tags {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 4px 0 0 0;
  padding: 0;
}

.tag {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
}

.tag-annual {
  background-color: var(--tag-annual-bg);
  color: var(--tag-annual-text);
}

.tag-edible {
  background-color: var(--tag-edible-bg);
  color: var(--tag-edible-text);
}

.tag-pollinator {
  background-color: var(--tag-pollinator-bg);
  color: var(--tag-pollinator-text);
}

.card-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background-color: var(--divider-color);
  border-bottom: 1px solid var(--divider-color);
}

.stat {
  background-color: var(--stat-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  gap: 4px;
}

.stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--stat-label-color);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--stat-value-color);
}

.card-footer {
  background-color: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.footer-date {
  color: var(--footer-text);
  font-size: 12px;
}

.footer-viability {
  color: var(--footer-text);
  font-size: 12px;
  font-weight: 600;
}
